\onehalfspacing
\bibliographystyle{plainnat}
\newcommand{\documenttitle}{Seguros del r\'egimen obligatorio del ISSSTE}
\newcommand{\documentsubtitle}{Contingencias, cobertura y sustento legal}
\newcommand{\documentsubject}{Actividad 7 - Derecho a la Seguridad Social}

\begin{document}
\begin{titlepage}
  \pagecolor{unadmPaper}\color{unadmInk}
  \begin{center}
