\node[nodo,below=0.45cm of s1a] (s1b) {Fundamento: arts.~27--43 LISSSTE};

\node[nodo,below=0.65cm of s2] (s2a) {Accidentes y enfermedades vinculados con el trabajo; incapacidades, muerte o desaparici\'on por delito};
\node[nodo,below=0.45cm of s2a] (s2b) {Atenci\'on m\'edica, rehabilitaci\'on, licencias y pensiones. Arts.~55--75 LISSSTE};

\node[nodo,below=0.65cm of s3] (s3a) {Retiro y p\'erdida del trabajo remunerado por edad; protege cesant\'ia y vejez mediante cuenta individual};
\node[nodo,below=0.45cm of s3a] (s3b) {Renta vitalicia o retiros programados. Arts.~76--113 LISSSTE};

\node[nodo,below=0.65cm of s4] (s4a) {Inhabilitaci\'on por causa ajena al trabajo y muerte de la persona trabajadora};
\node[nodo,below=0.45cm of s4a] (s4b) {Pensiones por invalidez y para familiares derechohabientes. Arts.~114--140 LISSSTE};

\foreach \x in {s1,s2,s3,s4}{\draw[enlace] (r) -- node[etiqueta,sloped,above]{comprende} (\x);}
\draw[enlace] (s1)--node[etiqueta,right]{cubre}(s1a); \draw[enlace](s1a)--node[etiqueta,right]{se sustenta}(s1b);
\draw[enlace] (s2)--node[etiqueta,right]{cubre}(s2a); \draw[enlace](s2a)--node[etiqueta,right]{otorga}(s2b);
\draw[enlace] (s3)--node[etiqueta,right]{cubre}(s3a); \draw[enlace](s3a)--node[etiqueta,right]{otorga}(s3b);
